-- LOCAL EXPERIMENT ONLY. All barriers remain closed; no external fence is proven.
-- Every BEFORE trigger is required; each check fails closed independently.
DROP TRIGGER IF EXISTS serial_final_completion_unimplemented;
CREATE TRIGGER serial_final_completion_integrity BEFORE INSERT ON serial_pilot_final_completions WHEN NOT (NOT EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name IN ('serial_continuation_session_not_ready','serial_continuation_permit_not_ready','serial_continuation_authorization_not_ready','serial_pilot_oracle_revoke_not_ready','serial_pilot_fence_not_ready','serial_pilot_hold_not_ready','serial_job_provenance_not_ready','serial_source_provenance_not_ready','serial_pilot_oracle_fence_not_ready','serial_pilot_attested_handoff_not_ready','serial_pilot_notice_release_not_ready','serial_ledger_stage_not_ready')) AND (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_continuation_session_insert','serial_continuation_session_no_update','serial_continuation_session_no_delete','serial_continuation_permit_insert','serial_continuation_permit_no_update','serial_continuation_permit_no_delete','serial_continuation_claim_insert','serial_continuation_claim_conflict','serial_continuation_claim_identity','serial_continuation_claim_review','serial_continuation_claim_delete','serial_continuation_completion_guard','serial_continuation_completion_no_update','serial_continuation_completion_no_delete','serial_continuation_authorization_insert','serial_continuation_authorization_no_update','serial_continuation_authorization_no_delete','serial_continuation_claim_phase'))=18 AND (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('stable_source_revision_expense_events_insert','stable_source_revision_expense_events_update','stable_source_revision_expense_events_delete','stable_source_revision_expense_documents_insert','stable_source_revision_expense_documents_update','stable_source_revision_expense_documents_delete','stable_source_revision_expense_document_links_insert','stable_source_revision_expense_document_links_update','stable_source_revision_expense_document_links_delete','stable_source_revision_expense_document_items_insert','stable_source_revision_expense_document_items_update','stable_source_revision_expense_document_items_delete','stable_source_revision_owner_personal_transactions_insert','stable_source_revision_owner_personal_transactions_update','stable_source_revision_owner_personal_transactions_delete','stable_source_revision_no_delete','stable_source_revision_no_replace','stable_source_revision_monotonic','stable_pre_cutover_no_delete','stable_pre_cutover_no_update','stable_pre_cutover_no_replace','stable_cutover_no_delete','stable_cutover_no_replace','stable_cutover_transition','stable_projection_no_delete','stable_projection_no_replace','stable_projection_transition'))=27 AND (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_ledger_stage_no_replace','serial_ledger_stage_no_update','serial_ledger_stage_no_delete'))=3 AND (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_pilot_notice_release_no_replace','serial_pilot_notice_release_no_update','serial_pilot_notice_release_no_delete'))=3 AND (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_pilot_round_insert','serial_pilot_items_insert','serial_pilot_items_no_update','serial_pilot_items_no_delete','serial_pilot_round_no_delete','serial_pilot_round_transition','serial_pilot_bindings_insert','serial_pilot_bindings_no_update','serial_pilot_bindings_no_delete','serial_pilot_fence_reservation','serial_pilot_fence_audit_no_replace','serial_pilot_fence_audit_no_update','serial_pilot_fence_audit_no_delete','serial_pilot_snapshot_insert_guard','serial_pilot_snapshot_audit'))=15 AND (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_source_provenance_no_update','serial_source_provenance_no_delete','serial_source_provenance_no_replace','serial_source_provenance_namespace_guard','serial_source_provenance_insert_guard','serial_source_provenance_update_guard','serial_source_provenance_delete_guard','serial_source_job_birth_guard','serial_job_provenance_insert_guard','serial_job_provenance_update_guard','serial_job_provenance_delete_guard','serial_job_provenance_activation_no_update','serial_job_provenance_activation_no_delete','serial_job_provenance_activation_no_replace','serial_job_provenance_source_gate','serial_pilot_hold_no_replace','serial_pilot_hold_no_update','serial_pilot_hold_no_delete','serial_pilot_oracle_fence_no_replace','serial_pilot_oracle_fence_no_update','serial_pilot_oracle_fence_no_delete','serial_pilot_attested_handoff_no_replace','serial_pilot_attested_handoff_no_update','serial_pilot_attested_handoff_no_delete'))=24 AND (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_pilot_oracle_revoke_insert','serial_pilot_oracle_revoke_no_update','serial_pilot_oracle_revoke_no_delete'))=3 AND (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('continuous_daily_cutover_prepared','continuous_daily_cutover_no_delete','continuous_daily_cutover_no_replace','continuous_daily_cutover_transition','continuous_daily_snapshot_prepared','continuous_daily_snapshot_no_delete','continuous_daily_snapshot_no_update','continuous_daily_snapshot_no_replace','continuous_daily_record_post_cutover','continuous_daily_post_no_delete','continuous_daily_post_no_update','continuous_daily_post_no_replace','continuous_expense_projection_target_fence','continuous_expense_cutover_no_processing'))=14 AND NOT EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name IN ('serial_final_receipt_not_ready','serial_final_completion_not_ready','serial_continuation_completion_not_ready')) AND (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_final_receipt_no_replace','serial_final_receipt_no_update','serial_final_receipt_no_delete','serial_ledger_stage_no_replace','serial_ledger_stage_no_update','serial_ledger_stage_no_delete','continuous_ledger_evidence_source','continuous_ledger_evidence_no_update','continuous_ledger_evidence_no_delete','continuous_ledger_evidence_no_replace','atomic_daily_marker_no_delete','atomic_daily_marker_no_update','atomic_daily_marker_no_replace','stable_expense_preimage_verified_source','stable_expense_preimage_no_update','stable_expense_preimage_no_delete','stable_expense_preimage_no_replace','continuous_report_attempt_insert','continuous_report_attempt_transition','continuous_report_attempt_no_delete','continuous_report_attempt_no_replace','continuous_daily_evidence_source','continuous_daily_evidence_no_update','continuous_daily_evidence_no_delete','continuous_daily_evidence_no_replace'))=25 AND (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_final_completion_guard','serial_final_completion_apply','serial_final_completion_no_replace','serial_final_completion_no_update','serial_final_completion_no_delete','serial_final_release_delete','serial_final_completion_integrity'))=7) BEGIN SELECT RAISE(ABORT,'final completion integrity unverified'); END;
CREATE TRIGGER serial_final_completion_guard BEFORE INSERT ON serial_pilot_final_completions WHEN NOT EXISTS(
WITH target AS (
   SELECT s.epoch_id,s.spreadsheet_id,s.job_id,s.nonce,h.worker_version,j.entity_key,j.entity_version,rev.revision,daily.source_digest,o.admitted_at
   FROM serial_pilot_continuation_sessions s JOIN serial_pilot_continuation_permits permit ON permit.epoch_id=s.epoch_id AND permit.job_id=s.job_id AND permit.operation_token=NEW.operation_token
   JOIN stable_workbook_claims c ON c.spreadsheet_id=s.spreadsheet_id AND c.operation_token=permit.operation_token AND c.state='HELD'
   JOIN sync_jobs j ON j.job_id=s.job_id AND j.entity_type='EXPENSE' AND j.status='COMPLETED' AND j.last_error IS NULL AND j.next_attempt_at IS NULL AND j.lease_token IS NULL AND j.lease_until IS NULL AND j.serial_provenance_version=1 AND j.serial_lease_generation=permit.lease_generation
   JOIN expense_events source ON source.expense_id=j.entity_key AND source.version=j.entity_version AND source.status='CONFIRMED'
   JOIN stable_recovery_epochs ep ON ep.epoch_id=s.epoch_id AND ep.spreadsheet_id=s.spreadsheet_id AND ep.target_type='EXPENSE' AND ep.target_key=j.entity_key AND ep.target_version=j.entity_version AND ep.state='ARMED'
   JOIN stable_recovery_operations o ON o.epoch_id=s.epoch_id AND o.operation_token=c.operation_token AND o.state='ADMITTED'
   JOIN serial_pilot_attested_handoffs h ON h.nonce=s.nonce AND h.successor_epoch_id=s.epoch_id AND h.successor_job_id=s.job_id AND h.worker_version=permit.worker_version
   JOIN serial_pilot_notice_release_receipts dr ON dr.nonce=s.nonce AND dr.epoch_id=s.epoch_id AND dr.successor_job_id=s.job_id AND dr.spreadsheet_id=s.spreadsheet_id
   JOIN stable_source_revision rev ON rev.singleton=1 AND rev.revision=dr.source_revision
   JOIN stable_recovery_operations dailyop ON dailyop.epoch_id=s.epoch_id AND dailyop.operation_token=dr.operation_token AND dailyop.state='VERIFIED'
   JOIN stable_projection_writes daily ON daily.spreadsheet_id=s.spreadsheet_id AND daily.entity_type='EXPENSE' AND daily.entity_id=j.entity_key AND daily.source_version=j.entity_version AND daily.projection='DAILY' AND daily.operation_token=dr.operation_token AND daily.state='VERIFIED' AND daily.sheet_id=NEW.daily_id AND daily.sheet_name=NEW.daily_name
   JOIN atomic_daily_marker_reservations dm ON dm.spreadsheet_id=daily.spreadsheet_id AND dm.sheet_id=daily.sheet_id AND dm.entity_id=daily.entity_id AND dm.source_version=daily.source_version AND dm.operation_token=daily.operation_token
   JOIN continuous_daily_write_evidence de ON de.spreadsheet_id=daily.spreadsheet_id AND de.entity_id=daily.entity_id AND de.sheet_id=daily.sheet_id AND de.sheet_name=daily.sheet_name AND de.source_version=daily.source_version AND de.source_digest=daily.source_digest AND de.operation_token=daily.operation_token AND de.marker=dm.marker
   JOIN stable_expense_projection_preimages dpi ON dpi.spreadsheet_id=daily.spreadsheet_id AND dpi.entity_type=daily.entity_type AND dpi.entity_id=daily.entity_id AND dpi.source_version=daily.source_version AND dpi.projection=daily.projection AND dpi.sheet_id=daily.sheet_id AND dpi.sheet_name=daily.sheet_name AND dpi.source_digest=daily.source_digest
   JOIN serial_pilot_oracle_fence f ON f.spreadsheet_id=s.spreadsheet_id AND f.fence_digest=s.fence_digest AND f.generation=s.fence_generation
   JOIN continuous_daily_cutovers cutover ON cutover.spreadsheet_id=s.spreadsheet_id AND cutover.state='ACTIVE' AND cutover.continuous_sheet_id=NEW.daily_id AND cutover.continuous_sheet_name=NEW.daily_name AND cutover.raw_sheet_id=NEW.raw_id AND cutover.raw_sheet_name=NEW.raw_name AND cutover.detail_sheet_id=NEW.detail_id AND cutover.detail_sheet_name=NEW.detail_name
   WHERE s.spreadsheet_id=NEW.spreadsheet_id AND h.worker_version=NEW.worker_version AND o.admitted_at<=NEW.provider_observed_at AND NEW.notice_observed_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND NOT EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name IN ('serial_final_completion_not_ready','serial_continuation_completion_not_ready')) AND (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_final_completion_guard','serial_final_completion_integrity','serial_final_completion_apply','serial_final_completion_no_replace','serial_final_completion_no_update','serial_final_completion_no_delete','serial_final_release_delete'))=7
    AND NOT EXISTS(SELECT 1 FROM serial_pilot_continuation_completions x WHERE x.epoch_id=s.epoch_id)
    AND NOT EXISTS(SELECT 1 FROM serial_pilot_oracle_revocations v WHERE v.spreadsheet_id=f.spreadsheet_id AND v.fence_digest=f.fence_digest AND v.fence_generation=f.generation)
    AND NOT EXISTS(SELECT 1 FROM stable_recovery_operations u WHERE u.epoch_id=s.epoch_id AND u.operation_token<>c.operation_token AND u.state<>'VERIFIED')
    AND NOT EXISTS(SELECT 1 FROM failed_jobs z WHERE z.queue_name='malipang-jobs' AND z.job_key='EXPENSE:'||j.entity_key||':'||j.entity_version AND z.status='OPEN')
  ), expected AS (
   SELECT entity_key entity_id,'EXPENSE_RAW' projection FROM target
   UNION ALL SELECT t.entity_key||'|'||i.item_id,'DETAIL' FROM target t JOIN expense_document_items i ON i.expense_id=t.entity_key
  ), proven AS (
   SELECT p.entity_id,p.projection,p.operation_token FROM target t JOIN serial_pilot_ledger_stage_receipts r ON r.epoch_id=t.epoch_id AND r.spreadsheet_id=t.spreadsheet_id AND r.job_id=t.job_id AND r.source_version=t.entity_version AND r.source_digest=t.source_digest AND r.source_revision=t.revision AND r.nonce=t.nonce AND r.worker_version=t.worker_version
   JOIN stable_recovery_operations op ON op.epoch_id=t.epoch_id AND op.operation_token=r.operation_token AND op.state='VERIFIED' AND op.admitted_at<=r.observed_at AND r.observed_at<=r.recorded_at
   JOIN stable_projection_writes p ON p.spreadsheet_id=r.spreadsheet_id AND p.entity_type='EXPENSE' AND p.entity_id=r.entity_id AND p.projection=r.projection AND p.sheet_id=r.sheet_id AND p.sheet_name=r.sheet_name AND p.source_version=r.source_version AND p.source_digest=r.source_digest AND p.operation_token=r.operation_token AND p.state='VERIFIED'
   JOIN atomic_daily_marker_reservations m ON m.spreadsheet_id=p.spreadsheet_id AND m.sheet_id=p.sheet_id AND m.entity_id=p.entity_id AND m.source_version=p.source_version AND m.operation_token=p.operation_token
   JOIN continuous_ledger_write_evidence le ON le.spreadsheet_id=p.spreadsheet_id AND le.entity_id=p.entity_id AND le.projection=p.projection AND le.operation_kind='CONFIRM' AND le.sheet_id=p.sheet_id AND le.sheet_name=p.sheet_name AND le.source_version=p.source_version AND le.operation_token=p.operation_token AND le.marker=r.ledger_marker AND le.before_digest=r.before_digest AND le.payload_digest=r.payload_digest
   JOIN stable_expense_projection_preimages pi ON pi.spreadsheet_id=p.spreadsheet_id AND pi.entity_type=p.entity_type AND pi.entity_id=p.entity_id AND pi.source_version=p.source_version AND pi.projection=p.projection AND pi.sheet_id=p.sheet_id AND pi.sheet_name=p.sheet_name AND pi.source_digest=p.source_digest
   WHERE (p.projection='EXPENSE_RAW' AND p.sheet_id=NEW.raw_id AND p.sheet_name=NEW.raw_name) OR (p.projection='DETAIL' AND p.sheet_id=NEW.detail_id AND p.sheet_name=NEW.detail_name)
  ) SELECT 1 FROM target t
   WHERE (SELECT count(*) FROM target)=1 AND (SELECT count(*) FROM expected)=(SELECT count(*) FROM proven)
    AND NOT EXISTS(SELECT entity_id,projection FROM expected EXCEPT SELECT entity_id,projection FROM proven)
    AND NOT EXISTS(SELECT entity_id,projection FROM proven EXCEPT SELECT entity_id,projection FROM expected)
    AND NOT EXISTS(SELECT 1 FROM serial_pilot_ledger_stage_receipts extra WHERE extra.epoch_id=t.epoch_id AND NOT EXISTS(SELECT 1 FROM proven matched WHERE matched.entity_id=extra.entity_id AND matched.projection=extra.projection AND matched.operation_token=extra.operation_token))
    AND (SELECT count(*) FROM stable_projection_writes p WHERE p.spreadsheet_id=t.spreadsheet_id AND p.entity_type='EXPENSE' AND (p.entity_id=t.entity_key OR substr(p.entity_id,1,length(t.entity_key)+1)=t.entity_key||'|'))=1+(SELECT count(*) FROM expected)
    AND NOT EXISTS(SELECT 1 FROM stable_projection_writes p WHERE p.spreadsheet_id=t.spreadsheet_id AND p.entity_type='EXPENSE' AND (p.entity_id=t.entity_key OR substr(p.entity_id,1,length(t.entity_key)+1)=t.entity_key||'|') AND NOT ((p.projection='DAILY' AND p.entity_id=t.entity_key) OR EXISTS(SELECT 1 FROM expected e WHERE e.entity_id=p.entity_id AND e.projection=p.projection)))
 AND t.epoch_id=NEW.epoch_id AND t.spreadsheet_id=NEW.spreadsheet_id AND t.job_id=NEW.job_id AND t.nonce=NEW.nonce AND t.worker_version=NEW.worker_version
 AND NEW.completed_at>=NEW.notice_observed_at AND NEW.completed_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND strftime('%Y-%m-%dT%H:%M:%fZ',NEW.completed_at)=NEW.completed_at
 AND EXISTS(SELECT 1 FROM serial_pilot_final_receipts r WHERE r.operation_token=NEW.operation_token AND r.epoch_id=t.epoch_id AND r.spreadsheet_id=t.spreadsheet_id AND r.job_id=t.job_id AND r.nonce=t.nonce AND r.worker_version=t.worker_version AND r.source_revision=t.revision AND r.source_digest=t.source_digest AND r.provider_algorithm='SHA256_MALIPANG_PROJECTION_SNAPSHOT_V1' AND r.notice_algorithm='SHA256_MALIPANG_NOTICE_POSTIMAGE_V1' AND r.provider_digest=NEW.provider_digest AND r.notice_digest=NEW.notice_digest AND r.provider_observed_at=NEW.provider_observed_at AND r.notice_observed_at=NEW.notice_observed_at)
) BEGIN SELECT RAISE(ABORT,'final completion evidence unverified'); END;

-- The session completion is recorded only as part of the verified final
-- insertion, after the exact old claim has been removed. A later claim is not
-- a reason to replay or delete it.
DROP TRIGGER IF EXISTS serial_continuation_completion_guard;
CREATE TRIGGER serial_continuation_completion_guard BEFORE INSERT ON serial_pilot_continuation_completions WHEN NOT EXISTS(
 SELECT 1 FROM serial_pilot_final_completions final
 JOIN serial_pilot_continuation_sessions session ON session.epoch_id=final.epoch_id AND session.spreadsheet_id=final.spreadsheet_id AND session.job_id=final.job_id AND session.nonce=final.nonce
 JOIN stable_recovery_operations op ON op.epoch_id=final.epoch_id AND op.operation_token=final.operation_token AND op.state='VERIFIED' AND op.verified_at=final.completed_at
 JOIN stable_recovery_epochs epoch ON epoch.epoch_id=final.epoch_id AND epoch.spreadsheet_id=final.spreadsheet_id AND epoch.state='COMPLETE'
 JOIN serial_pilot_final_receipts receipt ON receipt.operation_token=final.operation_token AND receipt.epoch_id=final.epoch_id AND receipt.spreadsheet_id=final.spreadsheet_id AND receipt.job_id=final.job_id AND receipt.nonce=final.nonce AND receipt.worker_version=final.worker_version AND receipt.provider_digest=final.provider_digest AND receipt.notice_digest=final.notice_digest AND receipt.provider_observed_at=final.provider_observed_at AND receipt.notice_observed_at=final.notice_observed_at
 JOIN stable_source_revision revision ON revision.singleton=1 AND revision.revision=receipt.source_revision
 JOIN serial_pilot_oracle_fence fence ON fence.spreadsheet_id=session.spreadsheet_id AND fence.fence_digest=session.fence_digest AND fence.generation=session.fence_generation
 WHERE final.epoch_id=NEW.epoch_id AND final.completed_at=NEW.completed_at
  AND NOT EXISTS(SELECT 1 FROM stable_workbook_claims claim WHERE claim.spreadsheet_id=final.spreadsheet_id)
  AND NOT EXISTS(SELECT 1 FROM serial_pilot_oracle_revocations revoked WHERE revoked.spreadsheet_id=fence.spreadsheet_id AND revoked.fence_digest=fence.fence_digest AND revoked.fence_generation=fence.generation)
  AND NOT EXISTS(SELECT 1 FROM sqlite_master WHERE type='trigger' AND name IN ('serial_final_completion_not_ready','serial_continuation_completion_not_ready'))
  AND (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('serial_final_completion_guard','serial_final_completion_apply','serial_final_completion_no_replace','serial_final_completion_no_update','serial_final_completion_no_delete','serial_final_release_delete','serial_final_completion_integrity'))=7
) BEGIN SELECT RAISE(ABORT,'final session completion unverified'); END;

-- This insertion is one SQLite statement: every transition and its guard
-- either commits together or rolls back with the completion row.
CREATE TRIGGER serial_final_completion_apply AFTER INSERT ON serial_pilot_final_completions BEGIN
 UPDATE stable_recovery_operations SET state='VERIFIED',verified_at=NEW.completed_at WHERE operation_token=NEW.operation_token AND epoch_id=NEW.epoch_id AND state='ADMITTED';
 SELECT CASE WHEN changes()<>1 THEN RAISE(ABORT,'final operation changed') END;
 UPDATE stable_recovery_epochs SET state='COMPLETE',updated_at=NEW.completed_at WHERE epoch_id=NEW.epoch_id AND spreadsheet_id=NEW.spreadsheet_id AND state='ARMED';
 SELECT CASE WHEN changes()<>1 THEN RAISE(ABORT,'final epoch changed') END;
 UPDATE stable_workbook_claims SET phase='SERIAL_FINAL_RELEASE' WHERE spreadsheet_id=NEW.spreadsheet_id AND operation_token=NEW.operation_token AND state='HELD' AND phase='SERIAL_CONTINUATION';
 SELECT CASE WHEN changes()<>1 THEN RAISE(ABORT,'final claim phase changed') END;
 DELETE FROM stable_workbook_claims WHERE spreadsheet_id=NEW.spreadsheet_id AND operation_token=NEW.operation_token AND state='HELD' AND phase='SERIAL_FINAL_RELEASE';
 SELECT CASE WHEN changes()<>1 THEN RAISE(ABORT,'final claim changed') END;
 INSERT INTO serial_pilot_continuation_completions(epoch_id,completed_at) VALUES(NEW.epoch_id,NEW.completed_at);
 SELECT CASE WHEN changes()<>1 THEN RAISE(ABORT,'final completion changed') END;
END;
